package android.content;import java.io.File;import android.content.pm.PackageManager;public class Context {public static final int MODE_PRIVATE=0;public final File files;public final ContentResolver resolver=new ContentResolver();public volatile Intent started;public volatile boolean filesOnMain;public final java.util.concurrent.atomic.AtomicInteger filesDirCalls=new java.util.concurrent.atomic.AtomicInteger();public Context(File f){files=f;}public Context(){this(new File("context-files"));}public Context getApplicationContext(){return this;}public File getFilesDir(){filesDirCalls.incrementAndGet();if(android.os.Looper.isMain())filesOnMain=true;return files;}public File getCacheDir(){return new File(files,"cache");}public String getPackageName(){return "com.lemon.lvoverseas";}public PackageManager getPackageManager(){return new PackageManager();}public ContentResolver getContentResolver(){return resolver;}public void startActivity(Intent i){started=i;}}
